css.value:
* {
    color: rgb(var(--Derived-Text---now-color_text--primary, #10171A));
    font-family: var(--Typography-Font---now-font-family, Lato);
    font-size: var(--Typography-Size-Form-controls-form-control-sm, 12px);
    font-style: normal;
    font-weight: 400;
    line-height: normal;
}

tabStyles.value:
.tabset-wrapper {
    height: 100% !important;
    min-height: 100vh;
}

@media (min-width: 640px) {
    .tabset-tabs {
        flex: 0 0 auto !important;
        border-inline-end: 1px solid rgb(var(--now-color_divider--tertiary));
        border-block: none;
        padding-left: var(--now-global-space--xl, 24px);
        padding-right: var(--now-global-space--xl, 24px);
        padding-top: var(--now-global-space--xl, 24px);
        padding-bottom: var(--now-global-space--xl, 24px);
    }
}

@media (max-width: 640px) {
    .tabset-tabs {
        width: auto;
    }
}

.tabset-container {
    width: 100%;
    padding-left: var(--now-global-space--xl, 24px);
    padding-right: var(--now-global-space--xl, 24px);
    padding-top: var(--now-global-space--xl, 24px);
    padding-bottom: var(--now-global-space--xl, 24px);
}
